(()=>{if(document.body.dataset.page!=='admin')return;function attach(){document.querySelectorAll('[data-product-row]').forEach(row=>{const p=BaoCatalog.get(row.dataset.productRow);if(!p?.bundle||row.querySelector('[data-config-bundle]'))return;const b=document.createElement('button');b.type='button';b.className='button';b.dataset.configBundle=p.code;b.textContent='Configurer le menu · 配置套餐';b.onclick=()=>edit(BaoCatalog.get(p.code));row.querySelector('.product-actions').append(b)})}
 function edit(product){const dialog=document.createElement('dialog');dialog.className='variant-dialog bundle-admin';dialog.innerHTML='<form class="variant-body"><button type="button" class="variant-close" aria-label="关闭">×</button><h2>Configurer le menu · 配置套餐</h2><label>中文名称<input name="dish" required maxlength="80"></label><label>Nom français<input name="fr" required maxlength="160"></label><label>Prix € · 套餐售价<input name="price" type="number" min="0" max="99999.99" step="0.01" required></label><label>主食份数 · Plats<input name="mainCount" type="number" min="1" max="6" required></label><label>饮品杯数 · Boissons<input name="drinkCount" type="number" min="1" max="6" required></label><fieldset data-mains><legend>可选主食 · Plats autorisés</legend></fieldset><fieldset data-drinks><legend>可选饮品 · Boissons autorisées</legend></fieldset><p class="note">每个位置可以重复选择同一商品，无补差价。售罄项不能下单。 / Choix répétables, sans supplément.</p><p role="status"></p><button class="button primary" type="submit">Enregistrer · 保存套餐</button></form>';const form=dialog.querySelector('form');for(const key of ['dish','fr','price'])form.elements[key].value=product[key];for(const key of ['mainCount','drinkCount'])form.elements[key].value=product.bundle[key];for(const [key,category] of [['mains',product.bundle.mainCategory],['drinks','饮品']]){const area=dialog.querySelector('[data-'+key+']');for(const p of BaoCatalog.all().filter(p=>p.category===category)){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.name=key;input.value=p.code;input.checked=product.bundle[key].includes(p.code);label.append(input,document.createTextNode(p.code+' · '+p.fr+' / '+p.dish));area.append(label)}}let busy=false;dialog.querySelector('.variant-close').onclick=()=>{if(!busy)dialog.close()};dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault()});dialog.addEventListener('close',()=>dialog.remove());form.onsubmit=async e=>{e.preventDefault();if(busy)return;const status=form.querySelector('[role=status]');try{const bundle={mainCategory:product.bundle.mainCategory,mainCount:Number(form.elements.mainCount.value),drinkCount:Number(form.elements.drinkCount.value),mains:[...form.querySelectorAll('[name=mains]:checked')].map(x=>x.value),drinks:[...form.querySelectorAll('[name=drinks]:checked')].map(x=>x.value)};if(!bundle.mains.length||!bundle.drinks.length)throw Error('请选择主食和饮品 / Sélectionnez plats et boissons');busy=true;form.querySelector('[type=submit]').disabled=true;await BaoCatalog.update(product.code,{bundle,dish:form.elements.dish.value,fr:form.elements.fr.value,price:Number(form.elements.price.value)},product.revision);dialog.close()}catch(e){status.textContent=e.message}finally{busy=false;form.querySelector('[type=submit]').disabled=false}};document.body.append(dialog);dialog.showModal()}
 window.addEventListener('DOMContentLoaded',()=>{attach();new MutationObserver(attach).observe(document.querySelector('#product-admin'),{childList:true,subtree:true})});window.addEventListener('bao-catalog-change',attach);
})();
